t.script:
(function () {
  "use strict";

  function $(sel, root){return (root||document).querySelector(sel);}
  function $val(id, d){ var el=$("#"+id); return el?el.value:d; }

  function uid(){ return 'spw_' + Math.random().toString(36).slice(2,10) + '_' + Date.now().toString(36); }

  async function loadImage(src){return new Promise(function(res,rej){var i=new Image();i.onload=function(){res(i)};i.onerror=rej;i.src=src;});}
  function readAsDataURL(file){return new Promise(function(res,rej){var r=new FileReader();r.onload=function(){res(r.result)};r.onerror=rej;r.readAsDataURL(file);});}

  async function postJSON(url, payload){
    try{
      var resp = await fetch(url,{method:"POST",headers:{"Content-Type":"application/json","X-Requested-With":"XMLHttpRequest"},credentials:"same-origin",body:JSON.stringify(payload)});
      var txt = await resp.text(); var data=null; try{data=JSON.parse(txt);}catch(_){}
      return {ok:resp.ok && !!data, data:data, status:resp.status, raw:txt};
    }catch(e){ return {ok:false, data:null, status:0, raw:String(e)}; }
  }

  function applyTransform(){
    var logo=$("#spw_logo_preview"); var base=$("#spw_product_img");
    if(!logo||!base) return;
    var sizePx=parseInt($val("spw_size","100"),10);
    var posX=parseInt($val("spw_pos_x","0"),10);
    var posY=parseInt($val("spw_pos_y","10"),10);
    var rot=parseInt($val("spw_rotation","0"),10);
    var bw=base.clientWidth, bh=base.clientHeight;
    var leftPx=bw*(0.5+posX/100); var topPx=bh*(0.6+posY/100);
    logo.style.position="absolute"; logo.style.left=leftPx+"px"; logo.style.top=topPx+"px";
    logo.style.transform="translate(-50%, -50%) rotate("+rot+"deg)"; logo.style.width=sizePx+"px";
    logo.classList.remove("d-none"); logo.style.opacity="1";
  }

  async function renderPNGDataURL(){
    var internalBaseEl=$("#spw-base-img");
    var baseSrc=(internalBaseEl && internalBaseEl.getAttribute("src")) || $val("spw_img_src","") || ($("#spw_product_img")||{}).getAttribute("src");
    if(!baseSrc) throw new Error("Sin imagen base.");
    var baseIm=await loadImage(baseSrc);
    var c=document.createElement("canvas"), ctx=c.getContext("2d");
    c.width=baseIm.naturalWidth||baseIm.width; c.height=baseIm.naturalHeight||baseIm.height;
    ctx.drawImage(baseIm,0,0,c.width,c.height);
    var logoEl=$("#spw_logo_preview");
    if(logoEl && logoEl.src){
      var baseEl=$("#spw_product_img"); var bw=baseEl.clientWidth, bh=baseEl.clientHeight;
      var br=baseEl.getBoundingClientRect(); var lr=logoEl.getBoundingClientRect();
      var cx=((lr.left+lr.width/2)-br.left)/bw*c.width; var cy=((lr.top+lr.height/2)-br.top)/bh*c.height;
      var w_norm=lr.width/bw; var drawW=w_norm*c.width;
      var logoIm=await loadImage(logoEl.src);
      var ratio=(logoIm.naturalHeight||logoIm.height)/(logoIm.naturalWidth||logoIm.width);
      var drawH=drawW*ratio; var rot=(parseInt($val("spw_rotation","0"),10)*Math.PI)/180;
      ctx.save(); ctx.translate(cx,cy); ctx.rotate(rot); ctx.drawImage(logoIm,-drawW/2,-drawH/2,drawW,drawH); ctx.restore();
    }
    return c.toDataURL("image/png");
  }

  async function addToCart(){
    var variantId=($val("spw_variant_id","")||"").trim();
    if(!variantId){ alert("Falta la variante del producto."); return; }
    var qty=parseFloat($val("spw_qty","1")||1)||1;
    var tech=((document.querySelector("input[name='spw_tech']:checked")||{}).value)||"";
    var svgColor=((document.querySelector("input[name='spw_svg_color']:checked")||{}).value)||"";
    var notes=($val("spw_notes","")||"").trim();
    var spw_token=uid();

    // 1) Crear línea nueva (ruta nativa Odoo)
    var r1=await postJSON("/shop/cart/update_json",{product_id:parseInt(variantId,10),add_qty:qty,spw_token:spw_token,display:false});
    if(!(r1.ok && r1.data && r1.data.line_id)){ alert("No se pudo añadir al carrito."); return; }
    var lineId=r1.data.line_id;

    // 2) Guardar meta en esa línea
    await postJSON("/spw/add_to_cart_meta",{variant_id:parseInt(variantId,10),qty:0,tech:tech,svg_color:svgColor,notes:notes,spw_token:spw_token});

    // 3) Adjuntar PNG
    try{
      var du=await renderPNGDataURL(); var pngB64=du?du.split('base64,')[1]:"";
      if(pngB64){ await postJSON("/spw/attach_png",{line_id:lineId,png_b64:pngB64}); }
    }catch(_){}

    // 4) Ir al carrito enfocando la línea
    window.location.href="/shop/cart?spw_line_id="+encodeURIComponent(lineId);
  }

  function init(){
    var logoInput=$("#spw_logo_input"); var logoEl=$("#spw_logo_preview");
    if(logoInput){
      logoInput.addEventListener("change", async function(ev){
        var f=ev.target.files && ev.target.files[0]; if(!f) return;
        var dataURL=await readAsDataURL(f); logoEl.src=dataURL; applyTransform();
      });
    }
    ["spw_size","spw_pos_x","spw_pos_y","spw_rotation"].forEach(function(id){ var el=document.getElementById(id); if(el) el.addEventListener("input", applyTransform); });
    window.spwReset=function(){ document.getElementById("spw_size").value=100; document.getElementById("spw_pos_x").value=0; document.getElementById("spw_pos_y").value=10; document.getElementById("spw_rotation").value=0; applyTransform(); };
    var dl=document.getElementById("spw_download_png"); if(dl){ dl.addEventListener("click", async function(){ try{ var du=await renderPNGDataURL(); var a=document.createElement("a"); a.href=du; a.download="personalizacion.png"; document.body.appendChild(a); a.click(); a.remove(); }catch(_){ alert("No se pudo generar el PNG."); } }); }
    var add=document.getElementById("spw_add_to_cart"); if(add){ add.addEventListener("click", addToCart); }
    applyTransform();
  }

  if(document.readyState==="loading"){ document.addEventListener("DOMContentLoaded", init); } else { init(); }
})();
